  if mf.exists():
   m=json.loads(mf.read_text());m['original_sha256']=m.get('sha256');m['sha256']=hashlib.sha256(raw).hexdigest();m['bytes']=len(raw);m['redaction_note']='Ephemeral form/challenge payload removed; no cookies persisted. Raw meaning and book evidence unchanged.'
